cd src && python3 - <<'EOF'
W,H=1280,720
d=open(f'preview_f0235.raw','rb').read()
# ASCII map: downsample to ~96 wide
cw=16; ch=16  # cell 16px -> 80x45
cols=W//cw; rows=H//ch
for ry in range(rows):
    line=[]
    for rx in range(cols):
        mx=0
        for yy in range(ry*ch,(ry+1)*ch):
            for xx in range(rx*cw,(rx+1)*cw):
                i=(yy*W+xx)*3
                mx=max(mx,(d[i]+d[i+1]+d[i+2])/3)
        if mx>200: line.append('#')
        elif mx>140: line.append('O')
        elif mx>90: line.append('o')
        elif mx>50: line.append('.')
        else: line.append(' ')
    print(''.join(line))
EOF

cd src && python3 - <<'EOF'
W,H=1280,720
d=open(f'preview_f0235.raw','rb').read()
bins={}
for y in range(H):
    for x in range(W):
        i=(y*W+x)*3
        if (d[i]+d[i+1]+d[i+2])/3>140:
            b=x//20
            bins[b]=bins.get(b,0)+1
for b in sorted(bins, key=lambda b:-bins[b])[:15]:
    print(f"x[{b*20}:{b*20+20}] -> {bins[b]}")
# now specifically the suspicious x ranges, with y distribution
for xlo in [200,1050]:
    ys=[]
    for y in range(H):
        for x in range(xlo,xlo+20):
            i=(y*W+x)*3
            if (d[i]+d[i+1]+d[i+2])/3>140:
                ys.append(y); break
    if ys:
        print(f"x~{xlo}: y from {min(ys)} to {max(ys)} count_rows={len(ys)}")
EOF

